#!/usr/bin/env node
/**
 * sync-claude-agents.mjs
 *
 * Generate the Claude Code runtime files from the canonical VS Code / GitHub Copilot sources:
 *
 *   .github/agents/*.agent.md   ->  .claude/agents/<name>.md
 *   .github/prompts/*.prompt.md ->  .claude/commands/<name>.md
 *
 * Usage (from the product repository root):
 *   node .github/scripts/sync-claude-agents.mjs           write the generated files
 *   node .github/scripts/sync-claude-agents.mjs --check   verify they are up to date
 *
 * Edit the .agent.md and .prompt.md sources, never the generated files.
 */

import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const AGENTS_SRC = join(ROOT, ".github", "agents");
const PROMPTS_SRC = join(ROOT, ".github", "prompts");
const AGENTS_OUT = join(ROOT, ".claude", "agents");
const COMMANDS_OUT = join(ROOT, ".claude", "commands");
const MARKER = "Generated by .github/scripts/sync-claude-agents.mjs";
const CHECK = process.argv.includes("--check");

/** Copilot tool aliases -> Claude Code tool names. */
const TOOL_MAP = {
  read: ["Read"],
  search: ["Grep", "Glob"],
  edit: ["Edit", "Write"],
  execute: ["Bash"],
  agent: ["Agent"],
  todo: ["TodoWrite"],
};

function fail(message) {
  console.error(`sync-claude-agents: ${message}`);
  process.exit(1);
}

function splitFrontmatter(text, file) {
  const normalised = text.replace(/\r\n/g, "\n");
  const match = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(normalised);
  if (!match) fail(`${file}: expected YAML frontmatter between --- markers`);
  return { yaml: match[1], body: match[2].trim() };
}

function unquote(value) {
  const trimmed = value.trim();
  if (trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length >= 2) {
    try {
      return JSON.parse(trimmed);
    } catch {
      return trimmed.slice(1, -1);
    }
  }
  if (trimmed.startsWith("'") && trimmed.endsWith("'") && trimmed.length >= 2) {
    return trimmed.slice(1, -1).replace(/''/g, "'");
  }
  return trimmed;
}

function splitInlineArray(value) {
  const inner = value.trim().slice(1, -1);
  const items = [];
  let current = "";
  let quote = null;
  for (const character of inner) {
    if (quote) {
      current += character;
      if (character === quote) quote = null;
      continue;
    }
    if (character === '"' || character === "'") {
      quote = character;
      current += character;
      continue;
    }
    if (character === ",") {
      items.push(unquote(current));
      current = "";
      continue;
    }
    current += character;
  }
  if (current.trim()) items.push(unquote(current));
  return items.filter((item) => item !== "");
}

/** Parse the small YAML subset used by the toolkit frontmatter. */
function parseFrontmatter(yaml, file) {
  const result = {};
  let currentKey = null;

  for (const line of yaml.split("\n")) {
    if (!line.trim() || line.trim().startsWith("#")) continue;

    const item = /^\s+-\s+(.*)$/.exec(line) || /^-\s+(.*)$/.exec(line);
    if (item && currentKey) {
      if (!Array.isArray(result[currentKey])) result[currentKey] = [];
      result[currentKey].push(unquote(item[1]));
      continue;
    }

    const keyValue = /^([A-Za-z0-9_-]+):\s*(.*)$/.exec(line);
    if (!keyValue) fail(`${file}: cannot parse frontmatter line: ${line}`);
    const [, key, value] = keyValue;
    currentKey = key;
    if (value.trim() === "") {
      result[key] = [];
    } else if (value.trim().startsWith("[")) {
      result[key] = splitInlineArray(value);
    } else {
      result[key] = unquote(value);
    }
  }

  return result;
}

function asArray(value) {
  if (value === undefined || value === null || value === "") return [];
  return Array.isArray(value) ? value : String(value).split(",").map((item) => item.trim()).filter(Boolean);
}

function slugify(name) {
  return String(name)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function mapTools(tools, file) {
  const mapped = [];
  for (const tool of tools) {
    const alias = TOOL_MAP[tool];
    if (alias) {
      mapped.push(...alias);
      continue;
    }
    if (tool.includes("/")) {
      const [server, name] = tool.split("/");
      if (!server || !name) fail(`${file}: cannot map tool "${tool}"`);
      mapped.push(name === "*" ? `mcp__${server}__*` : `mcp__${server}__${name}`);
      continue;
    }
    if (/^[A-Z]/.test(tool)) {
      mapped.push(tool);
      continue;
    }
    fail(`${file}: unknown tool alias "${tool}"`);
  }
  return [...new Set(mapped)];
}

function yamlString(value) {
  return JSON.stringify(String(value).replace(/\s+/g, " ").trim());
}

function relativePath(path) {
  return path.startsWith(ROOT) ? path.slice(ROOT.length + 1).replace(/\\/g, "/") : path;
}

function readAgents() {
  if (!existsSync(AGENTS_SRC)) fail(`source folder not found: ${AGENTS_SRC}`);
  return readdirSync(AGENTS_SRC)
    .filter((file) => file.endsWith(".agent.md"))
    .sort()
    .map((file) => {
      const sourcePath = join(AGENTS_SRC, file);
      const { yaml, body } = splitFrontmatter(readFileSync(sourcePath, "utf8"), file);
      const meta = parseFrontmatter(yaml, file);
      const displayName = String(meta.name ?? "").trim();
      if (!displayName) fail(`${file}: the name field is required`);
      if (!meta.description) fail(`${file}: the description field is required`);
      return {
        file,
        body,
        meta,
        displayName,
        description: String(meta.description),
        slug: slugify(displayName),
        tools: mapTools(asArray(meta.tools), file),
        allowedAgents: asArray(meta.agents),
        humanStarted: String(meta["disable-model-invocation"] ?? "").toLowerCase() === "true",
      };
    });
}

function readPrompts() {
  if (!existsSync(PROMPTS_SRC)) return [];
  return readdirSync(PROMPTS_SRC)
    .filter((file) => file.endsWith(".prompt.md"))
    .sort()
    .map((file) => {
      const sourcePath = join(PROMPTS_SRC, file);
      const { yaml, body } = splitFrontmatter(readFileSync(sourcePath, "utf8"), file);
      const meta = parseFrontmatter(yaml, file);
      if (!meta.description) fail(`${file}: the description field is required`);
      return {
        file,
        body,
        slug: slugify(file.replace(/\.prompt\.md$/, "")),
        description: meta.description,
        argumentHint: meta["argument-hint"] ? String(meta["argument-hint"]) : null,
      };
    });
}

function renderAgent(agent, slugByName) {
  const description = agent.humanStarted
    ? `Human-started lifecycle stage (do not invoke proactively). ${agent.description}`
    : String(agent.description);

  const tools = [...agent.tools];
  if (agent.allowedAgents.length > 0 && !tools.includes("Agent")) tools.push("Agent");

  const allowed = agent.allowedAgents
    .map((name) => {
      const slug = slugByName.get(name);
      if (!slug) fail(`${agent.file}: agents allowlist refers to unknown agent "${name}"`);
      return `\`${slug}\` (${name})`;
    })
    .join(", ");

  const spawnNote = allowed
    ? ` You may spawn only these subagents: ${allowed}. Do not spawn any other subagent.`
    : "";

  const toolsLine = tools.length > 0 ? `tools: ${yamlString(tools.join(", "))}\n` : "";

  return `---
name: ${agent.slug}
description: ${yamlString(description)}
${toolsLine}---

<!-- ${MARKER} from .github/agents/${agent.file}. Do not edit this file; edit the source and re-run the script. -->
> **Claude Code runtime.** You are the \`${agent.slug}\` subagent, the Claude Code form of "${agent.displayName}".${spawnNote} Never start a later PDLC stage; finish the task you were given, report the result, and stop.

${agent.body}
`;
}

function renderCommand(prompt) {
  const hint = prompt.argumentHint ? `argument-hint: ${yamlString(prompt.argumentHint)}\n` : "";
  return `---
description: ${yamlString(prompt.description)}
${hint}disable-model-invocation: true
---

<!-- ${MARKER} from .github/prompts/${prompt.file}. Do not edit this file; edit the source and re-run the script. -->
Arguments for this run: $ARGUMENTS

${prompt.body}
`;
}

function writeAll(outputs) {
  const expected = new Set();

  for (const [path, content] of outputs) {
    expected.add(path);
    if (!CHECK) mkdirSync(dirname(path), { recursive: true });

    const current = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (current === content) continue;
    if (!CHECK) writeFileSync(path, content, "utf8");
  }

  // Remove files this script generated earlier whose source no longer exists.
  for (const directory of [AGENTS_OUT, COMMANDS_OUT]) {
    if (!existsSync(directory)) continue;
    for (const file of readdirSync(directory).filter((name) => name.endsWith(".md"))) {
      const path = join(directory, file);
      if (expected.has(path)) continue;
      const content = readFileSync(path, "utf8");
      if (!content.includes(MARKER)) continue;
      if (!CHECK) rmSync(path);
    }
  }

  return expected;
}

function main() {
  const agents = readAgents();

  const slugByName = new Map();
  const slugByFile = new Map();
  for (const agent of agents) {
    if (slugByName.has(agent.displayName)) fail(`duplicate agent name "${agent.displayName}"`);
    if (slugByFile.has(agent.slug)) fail(`duplicate agent file name "${agent.slug}"`);
    slugByName.set(agent.displayName, agent.slug);
    slugByFile.set(agent.slug, agent.file);
  }

  const prompts = readPrompts();
  const outputs = new Map();

  for (const agent of agents) {
    outputs.set(join(AGENTS_OUT, `${agent.slug}.md`), renderAgent(agent, slugByName));
  }
  for (const prompt of prompts) {
    outputs.set(join(COMMANDS_OUT, `${prompt.slug}.md`), renderCommand(prompt));
  }

  const expected = writeAll(outputs);
  const stale = [...outputs.entries()].filter(([path, content]) => {
    if (!existsSync(path)) return true;
    return readFileSync(path, "utf8") !== content;
  });

  if (CHECK) {
    if (stale.length > 0) {
      for (const [path] of stale) console.error(`stale: ${relativePath(path)}`);
      fail("generated Claude Code files are out of date. Run: node .github/scripts/sync-claude-agents.mjs");
    }
    console.log(`Claude Code files are up to date (${expected.size} files).`);
    return;
  }

  console.log(`Wrote ${expected.size} Claude Code files:`);
  for (const path of [...expected].sort()) console.log(`  ${relativePath(path)}`);
}

main();
